package com.nigson.integration.carrier;

import java.time.*;
import java.util.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.transaction.PlatformTransactionManager;
import org.springframework.transaction.support.TransactionTemplate;
import com.nigson.integration.platform.AuditWriter;
import com.nigson.shared.events.EventCodec;
import com.nigson.shared.problem.*;

/** Owner-local cancellation fences. A submitted intent can only be reconciled, never resubmitted. */
public final class CarrierCancellationExecution {
 public record Claim(UUID id,UUID bookingId,long version,long bookingVersion,CarrierCancellationValues.Command command,List<String> pieces,String account,boolean writable,CarrierCancellationValues.Receipt pending){public Claim{pieces=List.copyOf(pieces);}@Override public String toString(){return "CarrierCancellationClaim[protected]";}}
 private final JdbcTemplate jdbc;private final TransactionTemplate tx;private final AuditWriter audit;private final Clock clock;private final UUID generation;private final Instant notBefore,approvalUntil;private final String mode,account;
 public CarrierCancellationExecution(JdbcTemplate jdbc,PlatformTransactionManager manager,AuditWriter audit,Clock clock,UUID generation,Instant notBefore,Instant approvalUntil,String mode,String account){this.jdbc=Objects.requireNonNull(jdbc);this.audit=Objects.requireNonNull(audit);this.clock=Objects.requireNonNull(clock);this.generation=ApiValues.uuid(generation.toString());this.notBefore=Objects.requireNonNull(notBefore);this.approvalUntil=Objects.requireNonNull(approvalUntil);if(!Set.of("MOCK","SANDBOX","LIVE").contains(mode)||account==null||!account.matches("[a-f0-9]{64}"))throw ApiValues.invalid();this.mode=mode;this.account=account;tx=new TransactionTemplate(manager);tx.setTimeout(3);}
 private java.sql.Timestamp stamp(Instant at){return java.sql.Timestamp.from(at);}
 private static long version(Map<String,Object> row){return ((Number)row.get("version")).longValue();}
 private void local(){jdbc.execute("SET LOCAL lock_timeout='500ms'");jdbc.execute("SET LOCAL statement_timeout='2s'");}
 private void audit(UUID id,long before){audit.append("integration-carrier-cancellation",AuditValues.ActorKind.SYSTEM,AuditValues.Action.QUEUE_REPLAY,AuditValues.Resource.QUEUE,id,id,AuditValues.Reason.RECONCILIATION,Map.of("version",before),Map.of("version",before+1),null);}
 private CarrierCancellationValues.Command command(Map<String,Object> row){var books=jdbc.queryForMap("SELECT business_key FROM integration.carrier_booking WHERE id=?",row.get("booking_id"));return new CarrierCancellationValues.Command((UUID)row.get("source_request_id"),(UUID)row.get("shipment_id"),ApiValues.uuid(books.get("business_key").toString().replace("carrier-booking:","")),row.get("reference").toString(),row.get("mode").toString(),((java.sql.Timestamp)row.get("requested_at")).toInstant());}
 public Optional<Claim> claim(){return tx.execute(status->{local();var books=jdbc.queryForList("SELECT b.* FROM integration.carrier_booking b WHERE b.provider='FEDEX' AND b.state IN ('BOOKED','CANCELLED') AND (b.lease_until IS NULL OR b.lease_until<=?) AND EXISTS(SELECT 1 FROM integration.carrier_cancellation c WHERE c.booking_id=b.id AND c.state IN ('QUEUED','SUBMITTING','UNKNOWN','ACK_PENDING') AND c.next_attempt_at<=? AND (c.lease_until IS NULL OR c.lease_until<=?)) ORDER BY b.id FOR UPDATE OF b SKIP LOCKED LIMIT 1",stamp(clock.instant()),stamp(clock.instant()),stamp(clock.instant()));if(books.isEmpty())return Optional.empty();var b=books.getFirst();var rows=jdbc.queryForList("SELECT * FROM integration.carrier_cancellation WHERE booking_id=? AND state IN ('QUEUED','SUBMITTING','UNKNOWN','ACK_PENDING') AND next_attempt_at<=? AND (lease_until IS NULL OR lease_until<=?) FOR UPDATE SKIP LOCKED",b.get("id"),stamp(clock.instant()),stamp(clock.instant()));if(rows.isEmpty())return Optional.empty();var c=rows.getFirst();var input=command(c);if(!CarrierCancellationValues.hash(input).equals(c.get("request_hash"))||!Objects.equals(b.get("tracking_number"),input.reference())||!Objects.equals(b.get("shipment_id"),input.shipmentId()))throw CarrierValues.rule();var pieces=new ArrayList<String>();var node=EventCodec.JSON.readTree(c.get("piece_numbers").toString());if(!node.isArray()||node.isEmpty()||node.size()>100)throw CarrierValues.rule();for(var p:node){if(!p.isString()||!p.asString().matches("[A-Za-z0-9]{10,40}")||pieces.contains(p.asString()))throw CarrierValues.rule();pieces.add(p.asString());}if(!pieces.contains(input.reference()))throw CarrierValues.rule();boolean writable="QUEUED".equals(c.get("state"))&&c.get("submitted_at")==null&&generation.equals(c.get("generation"))&&!input.requestedAt().isBefore(notBefore)&&approvalUntil.isAfter(clock.instant())&&mode.equals(input.mode())&&account.equals(c.get("account_hash"))&&"BOOKED".equals(b.get("state"));CarrierCancellationValues.Receipt pending="ACK_PENDING".equals(c.get("state"))?CarrierCancellationValues.receipt(EventCodec.JSON.readTree(c.get("callback_body").toString())):null;var lease=stamp(clock.instant().plusSeconds(120));jdbc.update("UPDATE integration.carrier_booking SET lease_until=?,version=version+1,updated_by='integration-carrier-cancellation',updated_at=? WHERE id=?",lease,stamp(clock.instant()),b.get("id"));jdbc.update("UPDATE integration.carrier_cancellation SET lease_until=?,attempt_count=attempt_count+1,version=version+1,updated_by='integration-carrier-cancellation',updated_at=? WHERE id=?",lease,stamp(clock.instant()),c.get("id"));audit((UUID)c.get("id"),version(c));return Optional.of(new Claim((UUID)c.get("id"),(UUID)b.get("id"),version(c)+1,version(b)+1,input,pieces,c.get("account_hash").toString(),writable,pending));});}
 private boolean lock(Claim c){local();var books=jdbc.queryForList("SELECT * FROM integration.carrier_booking WHERE id=? FOR UPDATE",c.bookingId());var rows=jdbc.queryForList("SELECT * FROM integration.carrier_cancellation WHERE id=? FOR UPDATE",c.id());if(books.isEmpty()||rows.isEmpty())return false;var b=books.getFirst();var row=rows.getFirst();return version(b)==c.bookingVersion()&&version(row)==c.version()&&b.get("lease_until")!=null&&row.get("lease_until")!=null&&((java.sql.Timestamp)b.get("lease_until")).toInstant().isAfter(clock.instant())&&((java.sql.Timestamp)row.get("lease_until")).toInstant().isAfter(clock.instant());}
 /** Changes the durable checkpoint before the caller is allowed to issue a provider write. */
 public Optional<Claim> submitting(Claim c){if(!c.writable())return Optional.empty();return tx.execute(status->{if(!lock(c))return Optional.empty();if(!approvalUntil.isAfter(clock.instant()))return Optional.empty();int changed=jdbc.update("UPDATE integration.carrier_cancellation SET state='SUBMITTING',submitted_at=?,version=version+1,updated_at=? WHERE id=? AND state='QUEUED' AND submitted_at IS NULL AND generation=?",stamp(clock.instant()),stamp(clock.instant()),c.id(),generation);if(changed!=1)return Optional.empty();audit(c.id(),c.version());return Optional.of(new Claim(c.id(),c.bookingId(),c.version()+1,c.bookingVersion(),c.command(),c.pieces(),c.account(),false,null));});}
 public Optional<Claim> outcome(Claim c,String state,String reason,Instant occurred){var receipt=new CarrierCancellationValues.Receipt(EventCodec.uuid7(clock.instant()),c.command().cancellationId(),c.command().shipmentId(),c.command().bookingRequestId(),c.command().reference(),c.command().mode(),state,occurred,reason);return tx.execute(status->{if(!lock(c))return Optional.empty();var row=jdbc.queryForMap("SELECT * FROM integration.carrier_cancellation WHERE id=?",c.id());if("UNKNOWN".equals(state)&&"UNKNOWN".equals(row.get("notified_state"))){release(c,"UNKNOWN",reason);return Optional.empty();}jdbc.update("UPDATE integration.carrier_cancellation SET state='ACK_PENDING',outcome_state=?,occurred_at=?,callback_id=?,callback_body=?::jsonb,error_code=?,version=version+1,updated_at=? WHERE id=?",state,stamp(occurred),receipt.commandId(),EventCodec.JSON.writeValueAsString(receipt),"NONE".equals(reason)?null:reason,stamp(clock.instant()),c.id());audit(c.id(),c.version());return Optional.of(new Claim(c.id(),c.bookingId(),c.version()+1,c.bookingVersion(),c.command(),c.pieces(),c.account(),false,receipt));});}
 private void release(Claim c,String state,String reason){jdbc.update("UPDATE integration.carrier_cancellation SET state=?,error_code=?,lease_until=NULL,next_attempt_at=?,version=version+1,updated_at=? WHERE id=?",state,"NONE".equals(reason)?null:reason,stamp(clock.instant().plusSeconds(900)),stamp(clock.instant()),c.id());jdbc.update("UPDATE integration.carrier_booking SET lease_until=NULL,version=version+1,updated_at=? WHERE id=?",stamp(clock.instant()),c.bookingId());audit(c.id(),c.version());}
 public boolean failed(Claim c){return Boolean.TRUE.equals(tx.execute(status->{if(!lock(c))return false;var row=jdbc.queryForMap("SELECT state FROM integration.carrier_cancellation WHERE id=?",c.id());release(c,"ACK_PENDING".equals(row.get("state"))?"ACK_PENDING":"UNKNOWN","PROVIDER_OUTCOME_UNKNOWN");return true;}));}
 public boolean acknowledged(Claim c){if(c.pending()==null)throw CarrierValues.rule();return Boolean.TRUE.equals(tx.execute(status->{if(!lock(c))return false;jdbc.update("UPDATE integration.carrier_cancellation SET notified_state=? WHERE id=?",c.pending().state(),c.id());release(c,c.pending().state(),c.pending().reasonCode());if("CANCELLED".equals(c.pending().state()))jdbc.update("UPDATE integration.carrier_booking SET state='CANCELLED',next_poll_at=NULL,last_provider_status='CANCELLED' WHERE id=?",c.bookingId());return true;}));}
}
